#include "engine/GrooveLibrary.h"
#include "DrummerData.h"     // generated by juce_add_binary_data (see CMakeLists.txt)

namespace ikaros
{

namespace
{
    // A slice's notes are stored as one flat array, three numbers a note:
    // piece, tick, velocity.
    std::vector<GrooveLibrary::Note> readNotes (const juce::var& flat)
    {
        std::vector<GrooveLibrary::Note> notes;

        if (auto* array = flat.getArray())
        {
            notes.reserve ((size_t) array->size() / 3);

            for (int i = 0; i + 2 < array->size(); i += 3)
            {
                const int piece = (*array)[i];

                if (! juce::isPositiveAndBelow (piece, numDrumPieces))
                    continue;   // a piece from a newer library: skip it

                notes.push_back ({ (DrumPiece) piece, (int) (*array)[i + 1], juce::jlimit (1, 127, (int) (*array)[i + 2]) });
            }
        }

        return notes;
    }
}

GrooveLibrary GrooveLibrary::fromJson (const juce::String& text)
{
    GrooveLibrary library;
    const auto json = juce::JSON::parse (text);

    if (auto* notes = json["sourceNotes"].getArray())
        for (auto& n : *notes)
            library.sourceNotes.push_back ((int) n);

    if (auto* map = json["td11"].getDynamicObject())
        for (auto& entry : map->getProperties())
            library.td11[entry.name.toString().getIntValue()] = entry.value.toString();

    if (auto* drummers = json["drummers"].getArray())
    {
        for (auto& d : *drummers)
        {
            Drummer drummer;
            drummer.info.id = d["id"].toString();
            drummer.info.name = d["name"].toString();
            drummer.info.description = d["description"].toString();
            drummer.info.kit = d["kit"].toString();
            drummer.swingSubdivision = (int) d["swing"] == 16 ? 16 : 8;

            if (auto* beats = d["beats"].getArray())
            {
                for (auto& b : *beats)
                {
                    Performance perf;
                    perf.source = b["src"].toString();
                    perf.style = b["style"].toString();
                    perf.player = b["drummer"];
                    perf.bpm = juce::jlimit (30.0, 300.0, (double) b["bpm"]);

                    if (auto* bars = b["bars"].getArray())
                        for (auto& bar : *bars)
                            perf.bars.push_back ({ (float) (double) bar["c"], (float) (double) bar["l"], readNotes (bar["n"]) });

                    if (! perf.bars.empty())
                        drummer.beats.push_back (std::move (perf));
                }
            }

            if (auto* fills = d["fills"].getArray())
            {
                for (auto& f : *fills)
                {
                    Fill fill;
                    fill.source = f["src"].toString();
                    fill.style = f["style"].toString();
                    fill.player = f["drummer"];
                    fill.bpm = juce::jlimit (30.0, 300.0, (double) f["bpm"]);
                    fill.beats = (int) f["beats"] == 2 ? 2 : 4;
                    fill.complexity = (float) (double) f["c"];
                    fill.loudness = (float) (double) f["l"];
                    fill.notes = readNotes (f["n"]);

                    if (! fill.notes.empty())
                        drummer.fills.push_back (std::move (fill));
                }
            }

            if (drummer.info.id.isNotEmpty() && ! drummer.beats.empty())
                library.drummers.push_back (std::move (drummer));
        }
    }

    return library;
}

const GrooveLibrary& GrooveLibrary::get()
{
    // A "magic static": built the first time this line runs, and C++11
    // guarantees that happens exactly once even with several threads.
    static const GrooveLibrary library = fromJson (juce::String::fromUTF8 (DrummerData::grooves_json,
                                                                           DrummerData::grooves_jsonSize));
    return library;
}

const GrooveLibrary::Drummer* GrooveLibrary::findDrummer (const juce::String& id) const
{
    for (auto& d : drummers)
        if (d.info.id == id)
            return &d;

    return nullptr;
}

const GrooveLibrary::Drummer* GrooveLibrary::findDrummerOrFirst (const juce::String& id) const
{
    if (auto* d = findDrummer (id))
        return d;

    return drummers.empty() ? nullptr : &drummers.front();
}

} // namespace ikaros
